# ---- Custom CUDA kernel for sum reduction over a specified dimension (FP32) ----
reduce_sum_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void reduce_sum_kernel(const float* input, const int dim_size_len, float* output, int total_rows) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_rows) {
        float sum = 0.0f;
        for (int i = 0; i < dim_size_len; ++i) {
            // For each row, the elements along the reduction dimension are stored consecutively.
            // Assuming input is laid out as [..., dim, ...] and we treat total_rows as number of rows
            // (all other indices fixed). The offset for element i in this row is idx * dim_size_len + i.
            sum += input[idx * dim_size_len + i];
        }
        output[idx] = sum;
    }
}

torch::Tensor reduce_sum_cuda(torch::Tensor x) {
    auto shape = x.shape();
    // For ModelNew the reduction dimension is 1 (dim=1). We'll hardcode dim_size_len = x.size(1).
    int dim_size_len = x.size(1);   # size of the dimension to reduce over
    int total_rows = 1;
    for (int i = 0; i < shape.size(); ++i) {
        if (i != 1) { // skip the reduction axis itself
            total_rows *= shape[i];
        }
    }

    float* out_ptr = x.data_ptr<float>();
    float* out_dims = torch::zeros_like(x); // placeholder for output tensor of same shape but with size 1 along dim=1

    const int block_size = 256;
    const int num_blocks = (total_rows + block_size - 1) / block_size;

    reduce_sum_kernel<<<num_blocks, block_size>>>(out_ptr, dim_size_len, out_dims.data_ptr<float>(), total_rows);

    return torch::from_blob(out_dims.data_ptr<float>(), out_dims.size(), torch::kFloat).contiguous().view(x.shape());
}
"""

